#!/usr/bin/env python3
import argparse,json,shutil,hashlib
from pathlib import Path
def main():
    p=argparse.ArgumentParser();p.add_argument('--evidence',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();dest=a.output/'sd-board';dest.mkdir(exist_ok=True,parents=True)
    report={'firmware_sha256':hashlib.sha256((a.evidence/'nuttx.bin').read_bytes()).hexdigest(),'flashed':True,'verified_banks':[],'apps':[],'performance':None,'screenshots':[]}
    if (a.evidence/'sd-verified.json').exists():report['verified_banks']=json.loads((a.evidence/'sd-verified.json').read_text())
    app=a.evidence/'board-test/apps-results.json'
    if app.exists():report['apps']=json.loads(app.read_text(encoding='utf-8'))['checks']
    perf=a.evidence/'board-test/grok-performance.json'
    if perf.exists():report['performance']=json.loads(perf.read_text(encoding='utf-8'))
    for src in (a.evidence/'board-test').glob('board-*.png'):
        shutil.copy2(src,dest/src.name);report['screenshots'].append(src.name)
    (dest/'results.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));(a.output/'board-test.html').write_text(PAGE,encoding='utf-8')
    print('SD_BOARD_REVIEW_UPDATED',len(report['verified_banks']),len(report['apps']))
PAGE='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SD 小球 · 烧录实测</title><style>body{margin:0;background:#f5f5f7;color:#252930;font:16px/1.6 "Segoe UI","Microsoft YaHei",sans-serif}main{max-width:1120px;margin:40px auto;padding:0 24px}h1{font-size:30px}h2{font-size:21px;margin-top:30px}p,small{color:#747985}table{width:100%;border-collapse:collapse;background:white;border-radius:16px;overflow:hidden}td,th{text-align:left;padding:12px 18px;border-bottom:1px solid #eee}section{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}figure{margin:0;background:white;border-radius:16px;overflow:hidden}img{width:100%;display:block}figcaption{padding:12px}code{font-size:12px;word-break:break-all}a{color:#7560a0}</style><main><h1>SD 小球 · 烧录实测</h1><p>首页、聊天头像与独立应用播放预渲染 RGB565+A8 帧。设备不运行 SVG；32 种表情保留。</p><p id="state">加载测试记录…</p><code id="sha"></code><h2>素材写卡与摘要校验</h2><table id="banks"></table><h2>实际播放性能</h2><table id="perf"></table><h2>应用入口测试</h2><table id="apps"></table><h2>实板画面</h2><section id="shots"></section><p><a href="home-sd.html?rev=sd-raw">查看原生离线设计渲染</a></p></main><script>async function refresh(){const d=await(await fetch('sd-board/results.json?ts='+Date.now())).json();document.querySelector('#sha').textContent='当前固件 SHA-256：'+d.firmware_sha256;document.querySelector('#state').textContent='已烧录 · 素材校验 '+d.verified_banks.length+'/5 · 应用检查 '+d.apps.filter(x=>x.status==='passed').length+'/'+d.apps.length;function table(id,headers,rows){const root=document.querySelector(id);root.replaceChildren();let tr=document.createElement('tr');for(const h of headers){const th=document.createElement('th');th.textContent=h;tr.append(th)}root.append(tr);for(const row of rows){tr=document.createElement('tr');for(const v of row){const td=document.createElement('td');td.textContent=v;tr.append(td)}root.append(tr)}}table('#banks',['素材包','大小','校验'],d.verified_banks.map(x=>[x.file,(x.bytes/1048576).toFixed(1)+' MiB','设备 SHA-256 一致']));table('#perf',['播放器','实测帧率','双缓冲'],(d.performance?.samples||[]).map(x=>[x.player,x.fps.toFixed(2)+' fps',(x.status.buffer/1024)+' KiB']));table('#apps',['入口','结果'],d.apps.map(x=>[x.name,x.status==='passed'?'通过':x.error||x.status]));const shots=document.querySelector('#shots');shots.replaceChildren();for(const name of d.screenshots){const f=document.createElement('figure'),im=document.createElement('img'),cap=document.createElement('figcaption');im.src='sd-board/'+name;cap.textContent=name+' · 实际板卡 framebuffer';f.append(im,cap);shots.append(f)}}refresh();setInterval(refresh,15000)</script></html>'''
if __name__=='__main__':main()
